/** A topic's other paintings fall back to its first when this build doesn't have them. */
export function sessionBoxIconAsset(id: SessionBoxIconId): number {
  const assets: Partial<Record<SessionBoxIconId, number>> = sessionBoxIconAssets;
  return assets[id] ?? sessionBoxIconAssets[sessionBoxBaseIconId(id)];
}
